// concept-words-001-declare: A word repair must declare a glossary term and concept term through the refinement menu
func TestConceptWords001Declare(t *testing.T) {
	s := scenarios.New(t, "concept-words-001-declare")
	s.Given(`the "concept-words-declare" project tree`)
	s.And(`the Product Owner answers "1" to every question`)
	s.When(`the Product Owner runs "us refine host --fix"`)
	s.Then(`the command exits with code 0`)
	s.And(`stdout matches undeclared domain word idempotency key`)
	s.And(`stdout matches action=apply`)
	s.And(`stdout matches judgement=words answer=pass`)
	s.And(`the file "docs/product/product.yaml" matches (?s)("terms":\s*\[\s*"idempotency key"|terms:\s*\n\s*- idempotency key)`)
	s.And(`the file "docs/product/product.yaml" matches (?s)("term":\s*"idempotency key",\s*"means":\s*"[^\"]+"|term: idempotency key\s+means:)`)
	s.And(`the only file changed outside "tmp" is "docs/product/product.yaml"`)
	s.Done()
}

